properties.query:
let baselineWindow = 24h;
let alertWindow = 15m;
let gateMultiplier = 2.5;
let floorBytes = 10000000.0;
let WhitelistedGCS = _GetWatchlist('C2_Whitelisted_GCS_List') | project GCS_IP;
let dynGate = toscalar(
    UAVExfilFlow_CL
    | where TimeGenerated > ago(baselineWindow)
    | where DestPort in (443, 53, 80)
    | summarize percentile(BytesTransferred, 99) * gateMultiplier
);
let byteGate = max_of(dynGate, floorBytes);
UAVExfilFlow_CL
| where TimeGenerated > ago(alertWindow)
| where DestPort in (443, 53, 80)
| where DestIp !in (WhitelistedGCS)
| where BytesTransferred > byteGate
| extend TriggerReason = strcat("C2은닉유출_상용포트_", tostring(DestPort), "_", tostring(toint(BytesTransferred/1000000)), "MB")
| extend Severity = "High"
| project TimeGenerated, UAVId, Operator, AssetType, DestIp, DestPort, BytesTransferred, TriggerReason, Severity
| order by TimeGenerated desc
